def read_file_content(workspace_id, path, encoding=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "read_file_content",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _norm_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path must not contain null bytes"
        p = p.strip()
        if not p.startswith("/"):
            p = "/" + p
        while "//" in p:
            p = p.replace("//", "/")
        if len(p) > 1 and p.endswith("/"):
            p = p[:-1]
        segs = p.split("/")[1:]
        if any(s == "" for s in segs):
            return None, "path must not contain empty segments"
        if any(s == ".." for s in segs):
            return None, "path must not contain '..'"
        # allow '.' but normalize it away
        if any(s == "." for s in segs):
            segs = [s for s in segs if s != "."]
            p = "/" + "/".join(segs) if segs else "/"
        return p, None

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        npath, perr = _norm_path(path)
        if perr:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=perr)
            return _err("VALIDATION_ERROR", perr)

        if encoding is not None and not isinstance(encoding, str):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="encoding must be a string")
            return _err("VALIDATION_ERROR", "encoding must be a string")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        fs_nodes = _load("fs_nodes.json")
        fs_versions = _load("fs_versions.json")

        node = next(
            (
                n
                for n in fs_nodes
                if isinstance(n, dict)
                and n.get("workspace_id") == workspace_id
                and n.get("path") == npath
                and n.get("status") == "active"
            ),
            None,
        )
        if not node:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="File not found.")
            return _err("NOT_FOUND", "File not found.")

        if node.get("node_type") != "file":
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Path refers to a directory, not a file.")
            return _err("VALIDATION_ERROR", "Path refers to a directory, not a file.")

        ver_id = node.get("current_version_id")
        if not isinstance(ver_id, str) or not ver_id:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="File has no content version.")
            return _err("NOT_FOUND", "File has no content version.")

        ver = next((v for v in fs_versions if isinstance(v, dict) and v.get("id") == ver_id and v.get("fs_node_id") == node.get("id")), None)
        if not ver:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="File content version not found.")
            return _err("NOT_FOUND", "File content version not found.")

        # Best-effort access timestamp update (not immutable)
        now = _now_iso()
        changed = False
        if node.get("last_accessed_at") != now:
            node["last_accessed_at"] = now
            node["updated_at"] = now
            changed = True
        if changed:
            _save("fs_nodes.json", fs_nodes)

        # Content is stored as text; "encoding" is metadata. If caller supplies encoding, validate label lightly.
        used_encoding = encoding or ver.get("encoding") or "utf-8"
        if not isinstance(used_encoding, str) or not used_encoding:
            used_encoding = "utf-8"

        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        resp = {
            "file": {
                "id": node.get("id"),
                "workspace_id": node.get("workspace_id"),
                "path": node.get("path"),
                "name": node.get("name"),
                "node_type": node.get("node_type"),
                "status": node.get("status"),
                "size_bytes": node.get("size_bytes"),
                "permissions_octal": node.get("permissions_octal"),
                "created_at": node.get("created_at"),
                "updated_at": node.get("updated_at"),
                "last_accessed_at": node.get("last_accessed_at"),
                "current_version_id": node.get("current_version_id"),
            },
            "version": {
                "id": ver.get("id"),
                "fs_node_id": ver.get("fs_node_id"),
                "created_by_run_id": ver.get("created_by_run_id"),
                "op_type": ver.get("op_type"),
                "encoding": ver.get("encoding"),
                "content_sha256": ver.get("content_sha256"),
                "diff_from_prev": ver.get("diff_from_prev"),
                "created_at": ver.get("created_at"),
                "updated_at": ver.get("updated_at"),
            },
            "content": ver.get("content_text"),
            "encoding": used_encoding,
        }
        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return resp
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def read_multiple_files_content(workspace_id, paths, encoding=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_path(p):
        if not isinstance(p, str) or p == "":
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path contains null byte"
        p = p.strip()
        if p == "":
            return None, "path must be a non-empty string"
        if not p.startswith("/"):
            p = "/" + p
        parts = p.split("/")
        for seg in parts[1:]:
            if seg == "" or seg == "." or seg == "..":
                return None, "path must be normalized and must not contain empty segments, '.' or '..'"
        return p, None

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(paths, list) or len(paths) < 1 or any((not isinstance(p, str) or p == "") for p in paths):
        return _err("VALIDATION_ERROR", "paths must be a non-empty array of non-empty strings")
    if encoding is not None and not isinstance(encoding, str):
        return _err("VALIDATION_ERROR", "encoding must be a string")

    # Load
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    fs_nodes = _load("fs_nodes.json")
    fs_versions = _load("fs_versions.json")

    # Ambient auth
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws or ws.get("status") != "active":
        return _err("UNAUTHORIZED", "No active workspace available for request")
    key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key:
        return _err("UNAUTHORIZED", "No active API key available for request")
    now = _now()
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    allowed = {"utf-8", "utf-16", "latin-1", "ascii"}
    if encoding is not None and encoding not in allowed:
        return _err("VALIDATION_ERROR", "Unsupported encoding", allowed=list(sorted(allowed)))

    results = []
    # index nodes by path
    nodes_by_path = {}
    for n in fs_nodes:
        if n.get("workspace_id") == workspace_id:
            nodes_by_path[n.get("path")] = n

    updated_any = False
    for raw in paths:
        pnorm, perr = _norm_path(raw)
        if perr:
            results.append({"path": raw, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": perr}})
            continue

        node = nodes_by_path.get(pnorm)
        if not node or node.get("status") != "active":
            results.append({"path": pnorm, "ok": False, "error": {"code": "NOT_FOUND", "message": "File not found"}})
            continue
        if node.get("node_type") != "file":
            results.append({"path": pnorm, "ok": False, "error": {"code": "CONFLICT", "message": "Path is not a file"}})
            continue
        ver_id = node.get("current_version_id")
        if not ver_id:
            results.append({"path": pnorm, "ok": False, "error": {"code": "NOT_FOUND", "message": "File has no content version"}})
            continue
        ver = next((v for v in fs_versions if v.get("id") == ver_id and v.get("fs_node_id") == node.get("id")), None)
        if not ver:
            results.append({"path": pnorm, "ok": False, "error": {"code": "NOT_FOUND", "message": "File version not found"}})
            continue

        node["last_accessed_at"] = now
        updated_any = True
        results.append({
            "path": pnorm,
            "ok": True,
            "content": ver.get("content_text"),
            "version": {"id": ver.get("id"), "encoding": ver.get("encoding"), "op_type": ver.get("op_type"), "created_at": ver.get("created_at")},
            "file": {"id": node.get("id"), "size_bytes": node.get("size_bytes"), "permissions_octal": node.get("permissions_octal")},
        })

    if updated_any:
        _save("fs_nodes.json", fs_nodes)

    return {
        "workspace_id": workspace_id,
        "results": results,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def write_file_content(workspace_id, path, content, encoding=None, created_by_run_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "write_file_content",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _norm_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path must not contain null bytes"
        p = p.strip()
        if not p.startswith("/"):
            p = "/" + p
        while "//" in p:
            p = p.replace("//", "/")
        if len(p) > 1 and p.endswith("/"):
            p = p[:-1]
        segs = p.split("/")[1:]
        if any(s == "" for s in segs):
            return None, "path must not contain empty segments"
        if any(s == ".." for s in segs):
            return None, "path must not contain '..'"
        if any(s == "." for s in segs):
            segs = [s for s in segs if s != "."]
            p = "/" + "/".join(segs) if segs else "/"
        return p, None

    def _parent_path(p):
        if p == "/":
            return None
        if "/" not in p[1:]:
            return "/"
        return p.rsplit("/", 1)[0] or "/"

    def _basename(p):
        return "/" if p == "/" else p.rsplit("/", 1)[-1]

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    def _sum_active_file_bytes(fs_nodes_rows, ws_id):
        total = 0
        for n in fs_nodes_rows:
            if not isinstance(n, dict):
                continue
            if n.get("workspace_id") != ws_id:
                continue
            if n.get("status") != "active":
                continue
            if n.get("node_type") != "file":
                continue
            sb = n.get("size_bytes")
            if isinstance(sb, int) and sb >= 0:
                total += sb
        return total

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        npath, perr = _norm_path(path)
        if perr:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=perr)
            return _err("VALIDATION_ERROR", perr)

        if not isinstance(content, str):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="content must be a string")
            return _err("VALIDATION_ERROR", "content must be a string")

        if encoding is not None and not isinstance(encoding, str):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="encoding must be a string")
            return _err("VALIDATION_ERROR", "encoding must be a string")

        # Relax run id validation to match real datastore ids (vxs_run_...); do not require exact vendor regex.
        if created_by_run_id is not None:
            if not isinstance(created_by_run_id, str) or not re.match(r"^vxs_run_[0-9A-Z]{18,}$", created_by_run_id):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="created_by_run_id must be a vxs_run_* id")
                return _err("VALIDATION_ERROR", "created_by_run_id must be a vxs_run_* id")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        fs_nodes = _load("fs_nodes.json")
        fs_versions = _load("fs_versions.json")
        query_runs = _load("query_runs.json")

        if created_by_run_id is not None:
            run = next((r for r in query_runs if isinstance(r, dict) and r.get("id") == created_by_run_id), None)
            if not run:
                _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="created_by_run_id not found")
                return _err("NOT_FOUND", "created_by_run_id not found")
            if run.get("workspace_id") != workspace_id:
                _audit("CONFLICT", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="conflict", error_message="created_by_run_id is not in this workspace")
                return _err("CONFLICT", "created_by_run_id is not in this workspace")

        # Disallow writing to '/' and require a parent directory.
        if npath == "/":
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Cannot write to '/'.")
            return _err("VALIDATION_ERROR", "Cannot write to '/'.")

        parent = _parent_path(npath)
        parent_node = next(
            (
                n
                for n in fs_nodes
                if isinstance(n, dict)
                and n.get("workspace_id") == workspace_id
                and n.get("path") == parent
                and n.get("status") == "active"
                and n.get("node_type") == "directory"
            ),
            None,
        )
        if not parent_node:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Parent directory does not exist.")
            return _err("NOT_FOUND", "Parent directory does not exist.")

        # Find or create file node; reject if directory exists at that path.
        existing = next((n for n in fs_nodes if isinstance(n, dict) and n.get("workspace_id") == workspace_id and n.get("path") == npath), None)
        now = _now_iso()

        if existing and existing.get("status") == "active" and existing.get("node_type") == "directory":
            _audit("CONFLICT", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="conflict", error_message="A directory already exists at that path.")
            return _err("CONFLICT", "A directory already exists at that path.")

        if existing and existing.get("status") == "deleted":
            # "Overwrite" by reviving as active file
            existing["status"] = "active"
            existing["node_type"] = "file"
            existing["parent_id"] = parent_node.get("id")
            existing["name"] = _basename(npath)
            existing["updated_at"] = now

        if not existing:
            node_id = _new_id("vxs_fs_")
            existing = {
                "id": node_id,
                "workspace_id": workspace_id,
                "parent_id": parent_node.get("id"),
                "path": npath,
                "name": _basename(npath),
                "node_type": "file",
                "status": "active",
                "size_bytes": 0,
                "permissions_octal": "0644",
                "created_at": now,
                "updated_at": now,
                "last_accessed_at": None,
                "current_version_id": None,
            }
            fs_nodes.append(existing)

        # Compute bytes for quota
        enc = encoding or "utf-8"
        try:
            new_size = len(content.encode(enc, errors="strict"))
        except LookupError:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Unknown encoding.")
            return _err("VALIDATION_ERROR", "Unknown encoding.")
        except UnicodeEncodeError:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Content cannot be encoded with the specified encoding.")
            return _err("VALIDATION_ERROR", "Content cannot be encoded with the specified encoding.")

        old_size = existing.get("size_bytes") if isinstance(existing.get("size_bytes"), int) else 0
        total_before = _sum_active_file_bytes(fs_nodes, workspace_id)
        total_after = total_before - max(old_size, 0) + new_size
        max_bytes = ws.get("max_files_bytes")
        if not isinstance(max_bytes, int) or max_bytes < 0:
            max_bytes = 0
        if total_after > max_bytes:
            _audit("QUOTA_EXCEEDED", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="quota_exceeded", error_message="Workspace max_files_bytes exceeded.")
            return _err("QUOTA_EXCEEDED", "Workspace max_files_bytes exceeded.", max_files_bytes=max_bytes, would_use_bytes=total_after)

        # Insert immutable version row
        ver_id = _new_id("vxs_fsv_")
        sha = hashlib.sha256(content.encode(enc, errors="strict")).hexdigest()
        ver_row = {
            "id": ver_id,
            "fs_node_id": existing.get("id"),
            "created_by_run_id": created_by_run_id,
            "op_type": "write",
            "encoding": enc,
            "content_text": content,
            "content_sha256": sha,
            "diff_from_prev": None,
            "created_at": now,
            "updated_at": now,
        }
        fs_versions.append(ver_row)

        # Update node pointers
        existing["current_version_id"] = ver_id
        existing["size_bytes"] = new_size
        existing["updated_at"] = now

        _save("fs_versions.json", fs_versions)
        _save("fs_nodes.json", fs_nodes)

        # Update key last used
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return {
            "file": existing,
            "version": ver_row,
        }
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def edit_file_content(workspace_id, path, edits, run_id=None, encoding=None, dry_run=None, **_extra):
    import json, os, datetime, time, re, hashlib, difflib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "edit_file_content",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _norm_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path must not contain null bytes"
        p = p.strip()
        if not p.startswith("/"):
            p = "/" + p
        while "//" in p:
            p = p.replace("//", "/")
        if len(p) > 1 and p.endswith("/"):
            p = p[:-1]
        segs = p.split("/")[1:]
        if any(s == "" for s in segs):
            return None, "path must not contain empty segments"
        if any(s == ".." for s in segs):
            return None, "path must not contain '..'"
        if any(s == "." for s in segs):
            segs = [s for s in segs if s != "."]
            p = "/" + "/".join(segs) if segs else "/"
        return p, None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    try:
        if dry_run is None:
            dry_run = False
        if not isinstance(dry_run, bool):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="dry_run must be boolean")
            return _err("VALIDATION_ERROR", "dry_run must be boolean")

        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_[0-9A-Z]{18,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        npath, perr = _norm_path(path)
        if perr:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=perr)
            return _err("VALIDATION_ERROR", perr)

        if not isinstance(edits, list) or len(edits) < 1:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="edits must be a non-empty array")
            return _err("VALIDATION_ERROR", "edits must be a non-empty array")

        for i, e in enumerate(edits):
            if not isinstance(e, dict) or "oldText" not in e or "newText" not in e:
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=f"Invalid edits[{i}]")
                return _err("VALIDATION_ERROR", f"Invalid edits[{i}]")
            if not isinstance(e.get("oldText"), str) or not e.get("oldText"):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=f"edits[{i}].oldText must be non-empty string")
                return _err("VALIDATION_ERROR", f"edits[{i}].oldText must be non-empty string")
            if not isinstance(e.get("newText"), str):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=f"edits[{i}].newText must be string")
                return _err("VALIDATION_ERROR", f"edits[{i}].newText must be string")

        if run_id is not None:
            if not isinstance(run_id, str) or not re.match(r"^vxs_run_[0-9A-Z]{18,}$", run_id):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="run_id must be a vxs_run_* id")
                return _err("VALIDATION_ERROR", "run_id must be a vxs_run_* id")

        if encoding is not None and not isinstance(encoding, str):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="encoding must be a string")
            return _err("VALIDATION_ERROR", "encoding must be a string")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        fs_nodes = _load("fs_nodes.json")
        fs_versions = _load("fs_versions.json")
        query_runs = _load("query_runs.json")

        if run_id is not None:
            run = next((r for r in query_runs if isinstance(r, dict) and r.get("id") == run_id), None)
            if not run:
                _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="run_id not found")
                return _err("NOT_FOUND", "run_id not found")
            if run.get("workspace_id") != workspace_id:
                _audit("CONFLICT", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="conflict", error_message="run_id is not in this workspace")
                return _err("CONFLICT", "run_id is not in this workspace")

        node = next(
            (
                n
                for n in fs_nodes
                if isinstance(n, dict)
                and n.get("workspace_id") == workspace_id
                and n.get("path") == npath
                and n.get("status") == "active"
            ),
            None,
        )
        if not node:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="File not found.")
            return _err("NOT_FOUND", "File not found.")

        if node.get("node_type") != "file":
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Path refers to a directory, not a file.")
            return _err("VALIDATION_ERROR", "Path refers to a directory, not a file.")

        ver_id = node.get("current_version_id")
        ver = next((v for v in fs_versions if isinstance(v, dict) and v.get("id") == ver_id and v.get("fs_node_id") == node.get("id")), None)
        if not ver:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="File content version not found.")
            return _err("NOT_FOUND", "File content version not found.")

        old_content = ver.get("content_text")
        if not isinstance(old_content, str):
            old_content = ""

        new_content = old_content
        applied = []
        for e in edits:
            old_t = e["oldText"]
            new_t = e["newText"]
            idx = new_content.find(old_t)
            if idx >= 0:
                new_content = new_content[:idx] + new_t + new_content[idx + len(old_t) :]
                applied.append({"method": "exact", "oldText": old_t, "newText": new_t})
            else:
                # fallback: trimmed line match
                lines = new_content.splitlines(True)
                target = old_t.strip()
                replaced = False
                for li, line in enumerate(lines):
                    if line.strip() == target and target != "":
                        lines[li] = new_t
                        replaced = True
                        break
                if replaced:
                    new_content = "".join(lines)
                    applied.append({"method": "trimmed_line", "oldText": old_t, "newText": new_t})
                else:
                    applied.append({"method": "not_found", "oldText": old_t, "newText": new_t})

        diff = "".join(
            difflib.unified_diff(
                old_content.splitlines(True),
                new_content.splitlines(True),
                fromfile=f"a{npath}",
                tofile=f"b{npath}",
                lineterm="",
            )
        )
        if diff and not diff.endswith("\n"):
            diff += "\n"

        if dry_run:
            _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
            return {
                "dry_run": True,
                "path": npath,
                "applied": applied,
                "diff": diff,
                "old_content": old_content,
                "new_content": new_content,
            }

        # No-op behavior: do not create a new version if content unchanged.
        if new_content == old_content:
            now = _now_iso()
            api_keys = _load("api_keys.json")
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
            _save("api_keys.json", api_keys)
            _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
            return {
                "dry_run": False,
                "path": npath,
                "applied": applied,
                "diff": diff,
                "no_op": True,
                "file": node,
                "version": ver,
                "content": old_content,
            }

        now = _now_iso()
        enc = encoding or ver.get("encoding") or "utf-8"

        # Validate encoding label by actually encoding (size is metadata-enforced elsewhere by write, but edits should be consistent)
        try:
            new_bytes = new_content.encode(enc, errors="strict")
        except LookupError:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Unknown encoding.")
            return _err("VALIDATION_ERROR", "Unknown encoding.")
        except UnicodeEncodeError:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="validation_error", error_message="Content cannot be encoded with the specified encoding.")
            return _err("VALIDATION_ERROR", "Content cannot be encoded with the specified encoding.")

        new_ver_id = _new_id("vxs_fsv_")
        sha = hashlib.sha256(new_bytes).hexdigest()
        new_ver = {
            "id": new_ver_id,
            "fs_node_id": node.get("id"),
            "created_by_run_id": run_id,
            "op_type": "edit",
            "encoding": enc,
            "content_text": new_content,
            "content_sha256": sha,
            "diff_from_prev": diff,
            "created_at": now,
            "updated_at": now,
        }
        fs_versions.append(new_ver)

        node["current_version_id"] = new_ver_id
        node["size_bytes"] = len(new_bytes)
        node["updated_at"] = now

        _save("fs_versions.json", fs_versions)
        _save("fs_nodes.json", fs_nodes)

        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return {
            "dry_run": False,
            "path": npath,
            "applied": applied,
            "diff": diff,
            "file": node,
            "version": new_ver,
            "content": new_content,
        }
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def create_directory(workspace_id, path, parents=None, run_id=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, workspace_id_ctx=None, tool=None, error_code=None, error_message=None, run_id_ctx=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"vxs_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.getpid()}_{len(logs)+1}",
            "tool_name": tool or "create_directory",
            "workspace_id": workspace_id_ctx,
            "api_key_id": api_key_id,
            "run_id": run_id_ctx,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _normalize_abs_path(p):
        if not isinstance(p, str) or len(p) < 1:
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path contains null byte"
        p = p.strip()
        if p == "":
            return None, "path must be non-empty"
        if not p.startswith("/"):
            p = "/" + p
        parts = p.split("/")
        out = []
        for seg in parts:
            if seg == "" or seg == ".":
                continue
            if seg == "..":
                return None, "path must not contain '..'"
            if seg.strip() == "":
                return None, "path contains empty segment"
            out.append(seg)
        return "/" + "/".join(out), None

    if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", tool="create_directory", error_code="validation_error", error_message="Invalid workspace_id", workspace_id_ctx=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    norm_path, perr = _normalize_abs_path(path)
    if perr:
        _log("error", tool="create_directory", error_code="validation_error", error_message=perr, workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", perr)
    if parents is None:
        parents = False
    if not isinstance(parents, bool):
        _log("error", tool="create_directory", error_code="validation_error", error_message="parents must be boolean", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "parents must be a boolean.")
    if run_id is not None and (not isinstance(run_id, str) or not re.match(r"^vxs_run_[0-9A-Z]{18,}$", run_id)):
        _log("error", tool="create_directory", error_code="validation_error", error_message="Invalid run_id", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid run_id format.")

    # auth: any active key in active workspace
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp or wsp.get("status") != "active":
        _log("error", tool="create_directory", error_code="unauthorized", error_message="Workspace not active", workspace_id_ctx=workspace_id, run_id_ctx=run_id)
        return _err("UNAUTHORIZED", "No authorized workspace context available for this request.")
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key:
        _log("error", tool="create_directory", error_code="unauthorized", error_message="No active API key", workspace_id_ctx=workspace_id, run_id_ctx=run_id)
        return _err("UNAUTHORIZED", "No authorized API key context available for this request.")
    api_key_id = key.get("id")

    if run_id is not None:
        query_runs = _load("query_runs.json")
        run = next((r for r in query_runs if isinstance(r, dict) and r.get("id") == run_id), None)
        if not run:
            _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory", error_code="not_found", error_message="run_id not found", run_id_ctx=run_id)
            return _err("NOT_FOUND", "run_id not found.", run_id=run_id)
        if run.get("workspace_id") != workspace_id:
            _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory", error_code="validation_error", error_message="run workspace mismatch", run_id_ctx=run_id)
            return _err("VALIDATION_ERROR", "run_id does not belong to workspace_id.", run_id=run_id)

    fs_nodes = _load("fs_nodes.json")
    now = _now()

    def _new_id(prefix, existing_ids):
        import secrets, string
        alphabet = string.ascii_uppercase + string.digits
        while True:
            s = "".join(secrets.choice(alphabet) for _ in range(20))
            _id = f"{prefix}_{s}"
            if _id not in existing_ids:
                return _id

    def _find_by_path(p):
        return next((n for n in fs_nodes if isinstance(n, dict) and n.get("workspace_id") == workspace_id and n.get("path") == p), None)

    # Ensure root exists (workspace root directory at "/")
    existing_ids = set(n.get("id") for n in fs_nodes if isinstance(n, dict))
    root = _find_by_path("/")
    if root is None:
        root_id = _new_id("vxs_fsn", existing_ids)
        root = {
            "id": root_id,
            "workspace_id": workspace_id,
            "parent_id": None,
            "path": "/",
            "name": "/",
            "node_type": "directory",
            "status": "active",
            "size_bytes": 0,
            "permissions_octal": "0755",
            "created_at": now,
            "updated_at": now,
            "last_accessed_at": None,
            "current_version_id": None
        }
        fs_nodes.append(root)
        existing_ids.add(root_id)

    # build segments to create
    if norm_path == "/":
        # mkdir "/" is idempotent
        root["updated_at"] = now
        _save("fs_nodes.json", fs_nodes)
        _log("ok", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory", run_id_ctx=run_id)
        return {
            "workspace_id": workspace_id,
            "path": "/",
            "created": False,
            "node": {"id": root.get("id"), "path": "/", "node_type": "directory", "status": root.get("status"), "updated_at": root.get("updated_at")}
        }

    parts = [seg for seg in norm_path.split("/") if seg][:]
    # choose whether to allow missing parents
    if not parents:
        # parent must exist and be an active directory
        parent_path = "/" + "/".join(parts[:-1]) if len(parts) > 1 else "/"
        parent_node = _find_by_path(parent_path)
        if not parent_node or parent_node.get("status") != "active" or parent_node.get("node_type") != "directory":
            _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory", error_code="not_found", error_message="Parent directory missing", run_id_ctx=run_id)
            return _err("NOT_FOUND", "Parent directory not found.", parent_path=parent_path)

    created_nodes = []
    cur_parent = root
    cur_path = ""
    for seg in parts:
        cur_path = (cur_path + "/" + seg) if cur_path else ("/" + seg)
        existing = _find_by_path(cur_path)
        if existing:
            if existing.get("status") != "active":
                # cannot resurrect deleted node (no transition defined)
                _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory",
                     error_code="invalid_transition", error_message="Directory is deleted", run_id_ctx=run_id)
                return _err("INVALID_TRANSITION", "Cannot create directory at a deleted path.", path=cur_path)
            if existing.get("node_type") != "directory":
                _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory",
                     error_code="conflict", error_message="File exists at path", run_id_ctx=run_id)
                return _err("CONFLICT", "A file already exists at that path.", path=cur_path)
            cur_parent = existing
            continue

        # create missing directory (only allowed if parents or we're at final segment with existing parent)
        if not parents and cur_path != norm_path:
            _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory", error_code="not_found", error_message="Missing intermediate parent", run_id_ctx=run_id)
            return _err("NOT_FOUND", "Missing intermediate parent directory. Set parents=true to create it.", path=cur_path)

        new_id = _new_id("vxs_fsn", existing_ids)
        existing_ids.add(new_id)
        node = {
            "id": new_id,
            "workspace_id": workspace_id,
            "parent_id": cur_parent.get("id"),
            "path": cur_path,
            "name": seg,
            "node_type": "directory",
            "status": "active",
            "size_bytes": 0,
            "permissions_octal": "0755",
            "created_at": now,
            "updated_at": now,
            "last_accessed_at": None,
            "current_version_id": None
        }
        fs_nodes.append(node)
        created_nodes.append({"id": new_id, "path": cur_path})
        cur_parent = node

    _save("fs_nodes.json", fs_nodes)
    _log("ok", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="create_directory", run_id_ctx=run_id)
    return {
        "workspace_id": workspace_id,
        "path": norm_path,
        "created": len(created_nodes) > 0,
        "created_nodes": created_nodes,
        "node": {"id": cur_parent.get("id"), "path": cur_parent.get("path"), "node_type": "directory", "status": cur_parent.get("status"), "updated_at": cur_parent.get("updated_at")}
    }

def list_directory_contents(workspace_id, path, include_deleted=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, workspace_id_ctx=None, tool=None, error_code=None, error_message=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"vxs_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.getpid()}_{len(logs)+1}",
            "tool_name": tool or "list_directory_contents",
            "workspace_id": workspace_id_ctx,
            "api_key_id": api_key_id,
            "run_id": None,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _normalize_abs_path(p):
        if not isinstance(p, str) or len(p) < 1:
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path contains null byte"
        p = p.strip()
        if p == "":
            return None, "path must be non-empty"
        if not p.startswith("/"):
            p = "/" + p
        parts = p.split("/")
        out = []
        for seg in parts:
            if seg == "" or seg == ".":
                continue
            if seg == "..":
                return None, "path must not contain '..'"
            if seg.strip() == "":
                return None, "path contains empty segment"
            out.append(seg)
        return "/" + "/".join(out), None

    if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message="Invalid workspace_id", workspace_id_ctx=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    norm_path, perr = _normalize_abs_path(path)
    if perr:
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message=perr, workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", perr)

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message="include_deleted must be boolean", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message="limit out of range", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message="cursor must be string", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort_by is None:
        sort_by = "name"
    if sort_by not in ("name", "node_type", "size_bytes", "updated_at"):
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message="Invalid sort_by", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "sort_by must be one of name, node_type, size_bytes, updated_at.")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log("error", tool="list_directory_contents", error_code="validation_error", error_message="Invalid sort_order", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.")

    # auth
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp or wsp.get("status") != "active":
        _log("error", tool="list_directory_contents", error_code="unauthorized", error_message="Workspace not active", workspace_id_ctx=workspace_id)
        return _err("UNAUTHORIZED", "No authorized workspace context available for this request.")
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key:
        _log("error", tool="list_directory_contents", error_code="unauthorized", error_message="No active API key", workspace_id_ctx=workspace_id)
        return _err("UNAUTHORIZED", "No authorized API key context available for this request.")
    api_key_id = key.get("id")

    fs_nodes = _load("fs_nodes.json")
    parent = next((n for n in fs_nodes if isinstance(n, dict) and n.get("workspace_id") == workspace_id and n.get("path") == norm_path), None)
    if not parent or parent.get("status") != "active":
        _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="list_directory_contents", error_code="not_found", error_message="Directory not found")
        return _err("NOT_FOUND", "Directory not found or is deleted.", path=norm_path)
    if parent.get("node_type") != "directory":
        _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="list_directory_contents", error_code="validation_error", error_message="Path is not a directory")
        return _err("VALIDATION_ERROR", "Path refers to a file, not a directory.", path=norm_path)

    # update last_accessed_at best-effort
    parent["last_accessed_at"] = _now()
    parent["updated_at"] = parent.get("updated_at") or _now()
    _save("fs_nodes.json", fs_nodes)

    children = []
    for n in fs_nodes:
        if not isinstance(n, dict):
            continue
        if n.get("workspace_id") != workspace_id:
            continue
        if n.get("parent_id") != parent.get("id"):
            continue
        if not include_deleted and n.get("status") != "active":
            continue
        children.append(n)

    reverse = (sort_order == "desc")
    def _key(n):
        v = n.get(sort_by)
        if sort_by in ("updated_at",):
            return v or ""
        if sort_by in ("size_bytes",):
            return v if isinstance(v, int) else -1
        if sort_by in ("node_type", "name"):
            return (v or "").lower()
        return v
    children.sort(key=_key, reverse=reverse)

    # cursor as base64 json {"offset": int}
    offset = 0
    if cursor:
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(payload)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="list_directory_contents", error_code="validation_error", error_message="Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="list_directory_contents", error_code="validation_error", error_message="Invalid cursor decode")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(children)
    page = children[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": offset + limit}).encode("utf-8")).decode("utf-8").rstrip("=")

    entries = []
    for n in page:
        prefix = "[DIR]" if n.get("node_type") == "directory" else "[FILE]"
        entries.append({
            "display": f"{prefix} {n.get('name')}",
            "id": n.get("id"),
            "path": n.get("path"),
            "name": n.get("name"),
            "node_type": n.get("node_type"),
            "status": n.get("status"),
            "size_bytes": n.get("size_bytes"),
            "permissions_octal": n.get("permissions_octal"),
            "created_at": n.get("created_at"),
            "updated_at": n.get("updated_at"),
            "last_accessed_at": n.get("last_accessed_at"),
            "current_version_id": n.get("current_version_id")
        })

    _log("ok", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="list_directory_contents")
    return {
        "workspace_id": workspace_id,
        "path": norm_path,
        "entries": entries,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
        "include_deleted": include_deleted
    }

def get_directory_tree(workspace_id, path, max_depth=None, include_deleted=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, workspace_id_ctx=None, tool=None, error_code=None, error_message=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"vxs_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.getpid()}_{len(logs)+1}",
            "tool_name": tool or "get_directory_tree",
            "workspace_id": workspace_id_ctx,
            "api_key_id": api_key_id,
            "run_id": None,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _normalize_abs_path(p):
        if not isinstance(p, str) or len(p) < 1:
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path contains null byte"
        p = p.strip()
        if p == "":
            return None, "path must be non-empty"
        if not p.startswith("/"):
            p = "/" + p
        parts = p.split("/")
        out = []
        for seg in parts:
            if seg == "" or seg == ".":
                continue
            if seg == "..":
                return None, "path must not contain '..'"
            if seg.strip() == "":
                return None, "path contains empty segment"
            out.append(seg)
        return "/" + "/".join(out), None

    if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log("error", tool="get_directory_tree", error_code="validation_error", error_message="Invalid workspace_id", workspace_id_ctx=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    norm_path, perr = _normalize_abs_path(path)
    if perr:
        _log("error", tool="get_directory_tree", error_code="validation_error", error_message=perr, workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", perr)

    if max_depth is None:
        max_depth = 10
    if not isinstance(max_depth, int) or max_depth < 0 or max_depth > 50:
        _log("error", tool="get_directory_tree", error_code="validation_error", error_message="max_depth out of range", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "max_depth must be an integer between 0 and 50.")
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", tool="get_directory_tree", error_code="validation_error", error_message="include_deleted must be boolean", workspace_id_ctx=workspace_id)
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")

    # auth
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp or wsp.get("status") != "active":
        _log("error", tool="get_directory_tree", error_code="unauthorized", error_message="Workspace not active", workspace_id_ctx=workspace_id)
        return _err("UNAUTHORIZED", "No authorized workspace context available for this request.")
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key:
        _log("error", tool="get_directory_tree", error_code="unauthorized", error_message="No active API key", workspace_id_ctx=workspace_id)
        return _err("UNAUTHORIZED", "No authorized API key context available for this request.")
    api_key_id = key.get("id")

    fs_nodes = _load("fs_nodes.json")
    by_id = {}
    children = {}
    for n in fs_nodes:
        if not isinstance(n, dict):
            continue
        if n.get("workspace_id") != workspace_id:
            continue
        by_id[n.get("id")] = n
        pid = n.get("parent_id")
        children.setdefault(pid, []).append(n)

    root = next((n for n in fs_nodes if isinstance(n, dict) and n.get("workspace_id") == workspace_id and n.get("path") == norm_path), None)
    if not root or (not include_deleted and root.get("status") != "active"):
        _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="get_directory_tree", error_code="not_found", error_message="Root not found")
        return _err("NOT_FOUND", "Path not found.", path=norm_path)
    if root.get("node_type") != "directory":
        _log("error", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="get_directory_tree", error_code="validation_error", error_message="Path is not a directory")
        return _err("VALIDATION_ERROR", "Path refers to a file, not a directory.", path=norm_path)

    # update last_accessed_at best-effort
    root["last_accessed_at"] = _now()
    root["updated_at"] = root.get("updated_at") or _now()
    _save("fs_nodes.json", fs_nodes)

    def _node_to_tree(n, depth):
        obj = {"name": n.get("name"), "type": n.get("node_type"), "path": n.get("path"), "id": n.get("id"), "status": n.get("status")}
        if n.get("node_type") == "directory" and depth < max_depth:
            kids = children.get(n.get("id"), [])
            if not include_deleted:
                kids = [k for k in kids if k.get("status") == "active"]
            kids.sort(key=lambda k: (k.get("node_type") != "directory", (k.get("name") or "").lower()))
            obj["children"] = [_node_to_tree(k, depth + 1) for k in kids]
        return obj

    tree = _node_to_tree(root, 0)
    _log("ok", api_key_id=api_key_id, workspace_id_ctx=workspace_id, tool="get_directory_tree")
    return {
        "workspace_id": workspace_id,
        "path": norm_path,
        "max_depth": max_depth,
        "include_deleted": include_deleted,
        "tree": tree
    }

def move_file_or_directory(workspace_id, source_path, destination_path, run_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "move_file_or_directory",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _norm_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path must not contain null bytes"
        p = p.strip()
        if not p.startswith("/"):
            p = "/" + p
        while "//" in p:
            p = p.replace("//", "/")
        if len(p) > 1 and p.endswith("/"):
            p = p[:-1]
        segs = p.split("/")[1:]
        if any(s == "" for s in segs):
            return None, "path must not contain empty segments"
        if any(s == ".." for s in segs):
            return None, "path must not contain '..'"
        if any(s == "." for s in segs):
            segs = [s for s in segs if s != "."]
            p = "/" + "/".join(segs) if segs else "/"
        return p, None

    def _basename(p):
        return "/" if p == "/" else p.rsplit("/", 1)[-1]

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_[0-9A-Z]{18,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        sp, e1 = _norm_path(source_path)
        if e1:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=e1)
            return _err("VALIDATION_ERROR", e1)
        dp, e2 = _norm_path(destination_path)
        if e2:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=e2)
            return _err("VALIDATION_ERROR", e2)

        if run_id is not None:
            if not isinstance(run_id, str) or not re.match(r"^vxs_run_[0-9A-Z]{18,}$", run_id):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="run_id must be a vxs_run_* id")
                return _err("VALIDATION_ERROR", "run_id must be a vxs_run_* id")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        fs_nodes = _load("fs_nodes.json")

        src_node = next(
            (
                n
                for n in fs_nodes
                if isinstance(n, dict)
                and n.get("workspace_id") == workspace_id
                and n.get("path") == sp
                and n.get("status") == "active"
            ),
            None,
        )
        if not src_node:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Source path not found.")
            return _err("NOT_FOUND", "Source path not found.")

        dst_exists = next(
            (
                n
                for n in fs_nodes
                if isinstance(n, dict)
                and n.get("workspace_id") == workspace_id
                and n.get("path") == dp
                and n.get("status") == "active"
            ),
            None,
        )
        if dst_exists:
            _audit("CONFLICT", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="conflict", error_message="Destination path already exists.")
            return _err("CONFLICT", "Destination path already exists.")

        # For directory moves, update all descendants path prefixes.
        now = _now_iso()
        src_type = src_node.get("node_type")
        updates = []
        if src_type == "directory":
            prefix = sp if sp.endswith("/") else sp + "/"
            dst_prefix = dp if dp.endswith("/") else dp + "/"

            # ensure not moving directory into its own subtree
            if dp == sp or dp.startswith(prefix):
                _audit("INVALID_TRANSITION", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="invalid_transition", error_message="Cannot move a directory into itself.")
                return _err("INVALID_TRANSITION", "Cannot move a directory into itself.")

            # Check uniqueness constraints for all affected nodes.
            affected = []
            for n in fs_nodes:
                if not isinstance(n, dict) or n.get("workspace_id") != workspace_id:
                    continue
                p = n.get("path")
                if p == sp or (isinstance(p, str) and p.startswith(prefix)):
                    affected.append(n)

            # Build a set of existing paths excluding affected (since they'll be rewritten)
            existing_paths = set()
            for n in fs_nodes:
                if not isinstance(n, dict) or n.get("workspace_id") != workspace_id or n.get("status") != "active":
                    continue
                if n in affected:
                    continue
                p = n.get("path")
                if isinstance(p, str):
                    existing_paths.add(p)

            # Check for collisions
            for n in affected:
                p = n.get("path")
                if p == sp:
                    np = dp
                else:
                    np = dst_prefix + p[len(prefix) :]
                if np in existing_paths:
                    _audit("CONFLICT", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="conflict", error_message="Move would collide with an existing path.")
                    return _err("CONFLICT", "Move would collide with an existing path.", colliding_path=np)
                updates.append((n, np))
                existing_paths.add(np)

            # Apply updates
            for n, np in updates:
                n["path"] = np
                n["name"] = _basename(np)
                n["updated_at"] = now
        else:
            # File move
            src_node["path"] = dp
            src_node["name"] = _basename(dp)
            src_node["updated_at"] = now
            updates.append((src_node, dp))

        _save("fs_nodes.json", fs_nodes)

        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return {
            "workspace_id": workspace_id,
            "source_path": sp,
            "destination_path": dp,
            "moved": [
                {"id": n.get("id"), "node_type": n.get("node_type"), "path": n.get("path"), "name": n.get("name")}
                for (n, _) in updates
            ],
        }
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def search_filesystem(workspace_id, start_path, pattern, exclude_globs=None, node_type=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, fnmatch, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "search_filesystem",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _norm_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, "path must be a non-empty string"
        if "\x00" in p:
            return None, "path must not contain null bytes"
        p = p.strip()
        if not p.startswith("/"):
            p = "/" + p
        while "//" in p:
            p = p.replace("//", "/")
        if len(p) > 1 and p.endswith("/"):
            p = p[:-1]
        segs = p.split("/")[1:]
        if any(s == "" for s in segs):
            return None, "path must not contain empty segments"
        if any(s == ".." for s in segs):
            return None, "path must not contain '..'"
        if any(s == "." for s in segs):
            segs = [s for s in segs if s != "."]
            p = "/" + "/".join(segs) if segs else "/"
        return p, None

    def _encode_cursor(i):
        raw = json.dumps({"i": i}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            pad = "=" * ((4 - (len(c) % 4)) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            i = obj.get("i", 0)
            if not isinstance(i, int) or i < 0:
                return None
            return i
        except Exception:
            return None

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_[0-9A-Z]{18,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        sp, e1 = _norm_path(start_path)
        if e1:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message=e1)
            return _err("VALIDATION_ERROR", e1)

        if not isinstance(pattern, str) or not pattern:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="pattern must be a non-empty string")
            return _err("VALIDATION_ERROR", "pattern must be a non-empty string")

        if exclude_globs is None:
            exclude_globs = []
        if not isinstance(exclude_globs, list) or any(not isinstance(g, str) for g in exclude_globs):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="exclude_globs must be an array of strings")
            return _err("VALIDATION_ERROR", "exclude_globs must be an array of strings")

        if node_type is None:
            node_type = "any"
        if node_type not in ("file", "directory", "any"):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="node_type must be one of file, directory, any")
            return _err("VALIDATION_ERROR", "node_type must be one of file, directory, any")

        # Relax limit validation: accept higher values, clamp to 2500 (observed calls use 2500)
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="limit must be >= 1")
            return _err("VALIDATION_ERROR", "limit must be >= 1")
        limit_eff = min(limit, 2500)

        start_i = _decode_cursor(cursor)
        if start_i is None:
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        fs_nodes = _load("fs_nodes.json")

        start_node = next(
            (
                n
                for n in fs_nodes
                if isinstance(n, dict)
                and n.get("workspace_id") == workspace_id
                and n.get("path") == sp
                and n.get("status") == "active"
                and n.get("node_type") == "directory"
            ),
            None,
        )
        if not start_node:
            # Read tools should return empty matches, not error, if filters match nothing.
            _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
            return {"matches": [], "total": 0, "has_more": False, "next_cursor": None}

        pat = pattern.lower()
        prefix = sp if sp.endswith("/") else sp + "/"

        # Precompute eligible active nodes under start_path
        candidates = []
        for n in fs_nodes:
            if not isinstance(n, dict):
                continue
            if n.get("workspace_id") != workspace_id or n.get("status") != "active":
                continue
            p = n.get("path")
            if not isinstance(p, str):
                continue
            if p != sp and not p.startswith(prefix):
                continue
            if node_type != "any" and n.get("node_type") != node_type:
                continue
            name = n.get("name") if isinstance(n.get("name"), str) else ""
            if pat not in name.lower():
                continue
            # Exclude globs match against workspace-relative path
            excluded = False
            for g in exclude_globs:
                try:
                    if fnmatch.fnmatch(p, g) or fnmatch.fnmatch(name, g):
                        excluded = True
                        break
                except Exception:
                    continue
            if excluded:
                continue
            candidates.append(n)

        # Stable sort by path then id for deterministic pagination
        candidates.sort(key=lambda x: (x.get("path") or "", x.get("id") or ""))

        total = len(candidates)
        page = candidates[start_i : start_i + limit_eff]
        next_i = start_i + len(page)
        has_more = next_i < total
        next_cursor = _encode_cursor(next_i) if has_more else None

        now = _now_iso()
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return {
            "matches": [
                {
                    "id": n.get("id"),
                    "path": n.get("path"),
                    "name": n.get("name"),
                    "node_type": n.get("node_type"),
                    "size_bytes": n.get("size_bytes"),
                    "permissions_octal": n.get("permissions_octal"),
                    "updated_at": n.get("updated_at"),
                }
                for n in page
            ],
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "limit": limit_eff,
        }
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

