def list_query_runs(workspace_id, status=None, tool_name=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    used_key_id = None
    status_out = "error"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Support Z suffix
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _audit(endpoint, status_code, workspace_id=None, api_key_id=None):
        # Best-effort audit; ignore parse errors in audit file only.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _find_auth_context():
        # Ambient authentication: pick any active api_key whose workspace is active.
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        wsp_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wsp = wsp_by_id.get(k.get("workspace_id"))
            if not wsp or wsp.get("status") != "active":
                continue
            return k, wsp
        return None, None

    def _decode_page_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok:
            return None
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_page_token(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id):
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=None, api_key_id=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=None)
        return _err("VALIDATION_ERROR", "Invalid status.")
    # Tool name enum in tool spec differs from datastore; accept only vendor enum.
    valid_tool = {
        "answer_query_websearch",
        "answer_query_direct",
        "explain_topic_with_docs",
        "get_doc_snippets",
        "generate_project_guidelines",
        "save_answer_to_file",
        "save_snippet_to_file",
        "save_guidelines_to_file",
    }
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in valid_tool):
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=None)
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=None)
        return _err("VALIDATION_ERROR", "Invalid page_size.")
    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=None)
        return _err("VALIDATION_ERROR", "Invalid created_after; expected RFC 3339 date-time.")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=None)
        return _err("VALIDATION_ERROR", "Invalid created_before; expected RFC 3339 date-time.")
    if ca and cb and not (ca < cb):
        _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=None)
        return _err("VALIDATION_ERROR", "created_after must be strictly before created_before.")

    # Authenticate (ambient)
    key, auth_wsp = _find_auth_context()
    if not key or not auth_wsp:
        _audit("list_query_runs", "UNAUTHORIZED", workspace_id=workspace_id, api_key_id=None)
        return _err("UNAUTHORIZED", "No active API key/workspace context available.")
    used_key_id = key.get("id")

    # Must be the given workspace and must be active
    if auth_wsp.get("id") != workspace_id:
        _audit("list_query_runs", "UNAUTHORIZED", workspace_id=workspace_id, api_key_id=used_key_id)
        return _err("UNAUTHORIZED", "API key not authorized for this workspace.")
    if auth_wsp.get("status") != "active" or key.get("status") != "active":
        _audit("list_query_runs", "UNAUTHORIZED", workspace_id=workspace_id, api_key_id=used_key_id)
        return _err("UNAUTHORIZED", "API key or workspace is not active.")

    # Pagination token
    token_obj = _decode_page_token(page_token)
    cursor = None
    if page_token is not None:
        if not token_obj or token_obj.get("v") != 1 or token_obj.get("workspace_id") != workspace_id:
            _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=used_key_id)
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        cursor = token_obj.get("cursor")  # expected created_at or (created_at,id)

    # Load and filter runs
    runs = _load("query_runs.json")
    if not isinstance(runs, list):
        runs = []

    def _run_created_dt(r):
        dt = _parse_rfc3339(r.get("created_at")) if isinstance(r, dict) else None
        return dt

    filtered = []
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None:
            # Map vendor save_* tool names to datastore tool names when possible
            tn = r.get("tool_name")
            mapped_ok = False
            if tool_name == tn:
                mapped_ok = True
            elif tool_name == "save_answer_to_file" and tn in ("save_answer_query_direct", "save_answer_query_websearch"):
                mapped_ok = True
            elif tool_name == "save_snippet_to_file" and tn == "save_doc_snippet":
                mapped_ok = True
            elif tool_name == "save_guidelines_to_file" and tn == "save_generate_project_guidelines":
                mapped_ok = True
            if not mapped_ok:
                continue
        dt = _run_created_dt(r)
        if ca and dt and not (dt > ca):
            continue
        if ca and dt is None:
            continue
        if cb and dt and not (dt < cb):
            continue
        if cb and dt is None:
            continue
        filtered.append(r)

    # Sort newest-first (created_at desc, tie by id desc)
    def _sort_key(r):
        dt = _run_created_dt(r)
        # None sorts last
        ts = dt.timestamp() if dt else -1e30
        return (ts, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor: cursor is a dict {"created_at": "...", "id": "..."} representing last item returned
    if cursor is not None:
        if not isinstance(cursor, dict) or "created_at" not in cursor or "id" not in cursor:
            _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=used_key_id)
            return _err("VALIDATION_ERROR", "Invalid page_token cursor.")
        cdt = _parse_rfc3339(cursor.get("created_at"))
        cid = cursor.get("id")
        if cdt is None or not isinstance(cid, str):
            _audit("list_query_runs", "VALIDATION_ERROR", workspace_id=workspace_id, api_key_id=used_key_id)
            return _err("VALIDATION_ERROR", "Invalid page_token cursor.")
        # Skip until after the cursor (newest-first)
        def _after_cursor(r):
            rdt = _run_created_dt(r)
            rid = r.get("id") or ""
            if rdt is None:
                return False
            if rdt.timestamp() < cdt.timestamp():
                return True
            if rdt.timestamp() == cdt.timestamp() and rid < cid:
                return True
            return False
        filtered = [r for r in filtered if _after_cursor(r)]

    page = filtered[:page_size]
    has_more = len(filtered) > len(page)
    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _encode_page_token({
            "v": 1,
            "workspace_id": workspace_id,
            "cursor": {"created_at": last.get("created_at"), "id": last.get("id")}
        })

    # Update last_used_at on successful auth
    api_keys = _load("api_keys.json")
    changed = False
    for k in api_keys if isinstance(api_keys, list) else []:
        if isinstance(k, dict) and k.get("id") == used_key_id:
            k["last_used_at"] = _now_iso()
            k["updated_at"] = k.get("updated_at") or _now_iso()
            changed = True
            break
    if changed:
        _save("api_keys.json", api_keys)

    status_out = "ok"
    _audit("list_query_runs", status_out, workspace_id=workspace_id, api_key_id=used_key_id)
    return {
        "query_runs": page,
        "total": len(filtered) + (0 if cursor is None else 0),
        "page_size": page_size,
        "has_more": has_more,
        "next_page_token": next_token
    }

def get_query_run(workspace_id, query_run_id, include_sources=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "get_query_run",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    try:
        if include_sources is None:
            include_sources = False
        if not isinstance(include_sources, bool):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="include_sources must be boolean")
            return _err("VALIDATION_ERROR", "include_sources must be boolean")

        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        # Relax id pattern to accept real datastore ids (vxs_run_...)
        if not isinstance(query_run_id, str) or not re.match(r"^vxs_run_[0-9A-Z]{18,}$", query_run_id):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="Invalid query_run_id format.")
            return _err("VALIDATION_ERROR", "Invalid query_run_id format.")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        query_runs = _load("query_runs.json")
        run = next((r for r in query_runs if isinstance(r, dict) and r.get("id") == query_run_id), None)
        if not run:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Query run not found.")
            return _err("NOT_FOUND", "Query run not found.")

        if run.get("workspace_id") != workspace_id:
            # This is not an auth failure; it's simply not in this workspace.
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Query run not found.")
            return _err("NOT_FOUND", "Query run not found.")

        resp = {"query_run": run}
        if include_sources:
            web_sources = _load("web_sources.json")
            sources = [s for s in web_sources if isinstance(s, dict) and s.get("query_run_id") == query_run_id]
            sources.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**9, x.get("id") or ""))
            resp["sources"] = sources

        now = _now_iso()
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return resp
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def cancel_query_run(workspace_id, query_run_id, reason=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

