            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "cancel_query_run",
                "workspace_id": workspace_id_ctx,
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Authentication requires an active workspace."
        key = next(
            (k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"),
            None,
        )
        if not key:
            return None, None, "UNAUTHORIZED", "Authentication requires an active API key for this workspace."
        return ws, key, None, None

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        # Relax id pattern to accept real datastore ids (vxs_run_...)
        if not isinstance(query_run_id, str) or not re.match(r"^vxs_run_[0-9A-Z]{18,}$", query_run_id):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="Invalid query_run_id format.")
            return _err("VALIDATION_ERROR", "Invalid query_run_id format.")

        if reason is not None:
            if not isinstance(reason, str):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="reason must be a string")
                return _err("VALIDATION_ERROR", "reason must be a string")
            if len(reason) > 500:
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="reason too long")
                return _err("VALIDATION_ERROR", "reason too long (maxLength=500)")

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        query_runs = _load("query_runs.json")
        run = next((r for r in query_runs if isinstance(r, dict) and r.get("id") == query_run_id), None)
        if not run:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Query run not found.")
            return _err("NOT_FOUND", "Query run not found.")

        if run.get("workspace_id") != workspace_id:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Query run not found.")
            return _err("NOT_FOUND", "Query run not found.")

        cur = run.get("status")
        if cur not in ("queued", "running"):
            _audit("INVALID_TRANSITION", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="invalid_transition", error_message="Run is already in a terminal state.")
            return _err("INVALID_TRANSITION", "Run is already in a terminal state.", status=cur)

        now = _now_iso()
        run["status"] = "cancelled"
        run["updated_at"] = now
        if reason:
            run["error_code"] = "cancelled"
            run["error_message"] = reason
        else:
            run["error_code"] = "cancelled"
            run["error_message"] = run.get("error_message") or "Cancelled by user."

        _save("query_runs.json", query_runs)

        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return {"query_run": run}
    except Exception as e:
        _audit("FAILED", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def list_workspaces(status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status_code, workspace_id=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "list_workspaces",
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "status": status_code,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _decode(tok):
        if tok is None:
            return 0
        if not isinstance(tok, str) or not tok:
            return None
        try:
            pad = "=" * ((4 - (len(tok) % 4)) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset", 0)
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode(off):
        raw = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _resolve_ambient_auth():
        # No explicit credential param: pick any active API key whose workspace is active.
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if ws and ws.get("status") == "active":
                return ws, k
        return None, None

    try:
        if status is not None:
            if status not in ("active", "suspended", "deleted"):
                _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid status filter.")
                return _err("VALIDATION_ERROR", "Invalid status filter.")

        if page_size is None:
            page_size = 50
        if not isinstance(page_size, int) or not (1 <= page_size <= 200):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="page_size must be in 1..200")
            return _err("VALIDATION_ERROR", "page_size must be in 1..200")

        offset = _decode(page_token)
        if offset is None:
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid page_token")
            return _err("VALIDATION_ERROR", "Invalid page_token")

        ws_ctx, key = _resolve_ambient_auth()
        if not key:
            _audit("UNAUTHORIZED", error_code="unauthorized", error_message="Authentication requires an active API key and workspace.")
            return _err("UNAUTHORIZED", "Authentication requires an active API key and workspace.")

        workspaces = _load("workspaces.json")
        rows = [w for w in workspaces if isinstance(w, dict)]
        if status is not None:
            rows = [w for w in rows if w.get("status") == status]

        # "Accessible to the calling API key": in this datastore model, keys belong to a workspace;
        # list returns only that workspace (and possibly others with same key? none). Keep strict: only that workspace_id.
        rows = [w for w in rows if w.get("id") == key.get("workspace_id")]

        rows.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))

        total = len(rows)
        page = rows[offset : offset + page_size]
        next_off = offset + len(page)
        next_token = _encode(next_off) if next_off < total else None

        now = _now_iso()
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _audit("OK", workspace_id=key.get("workspace_id"), api_key_id=key.get("id"))
        return {
            "workspaces": page,
            "total": total,
            "page_size": page_size,
            "next_page_token": next_token,
        }
    except Exception as e:
        _audit("FAILED", error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error.", detail=str(e))

def update_workspace(workspace_id, name=None, vertex_model=None, allow_web_search=None, max_requests_per_day=None, max_files_bytes=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0068000" if __import__("os").path.isdir("./environment_mix/0068000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status_code, workspace_id_ctx=None, api_key_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"vxs_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "update_workspace",
            "workspace_id": workspace_id_ctx,
            "api_key_id": api_key_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _resolve_auth_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws:
            return None, None, "NOT_FOUND", "Workspace not found."
        # must authenticate via active api_key and active workspace (rule); for updates, if workspace not active, still allow status transition? vendor says refuses if not accessible and key/workspace not active.
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if not key:
            return None, None, "UNAUTHORIZED", "No active API key available for this workspace."
        if ws.get("status") != "active":
            return None, None, "UNAUTHORIZED", "Workspace is not active."
        return ws, key, None, None

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^vxs_wsp_01H[A-Z0-9]{15,}$", workspace_id):
            _audit("VALIDATION_ERROR", error_code="validation_error", error_message="Invalid workspace_id format.")
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        if name is not None:
            if not isinstance(name, str) or not (1 <= len(name) <= 200):
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="name must be 1..200 chars")
                return _err("VALIDATION_ERROR", "name must be 1..200 chars")
        if vertex_model is not None:
            if not isinstance(vertex_model, str) or not vertex_model.strip():
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="vertex_model must be a non-empty string")
                return _err("VALIDATION_ERROR", "vertex_model must be a non-empty string")
            if vertex_model != "gemini-1.5-pro-latest":
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="Unsupported vertex_model")
                return _err("VALIDATION_ERROR", "Unsupported vertex_model", allowed=["gemini-1.5-pro-latest"])
        if allow_web_search is not None and not isinstance(allow_web_search, bool):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="allow_web_search must be boolean")
            return _err("VALIDATION_ERROR", "allow_web_search must be boolean")
        if max_requests_per_day is not None:
            if not isinstance(max_requests_per_day, int) or max_requests_per_day < 0 or max_requests_per_day > 1000000:
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="max_requests_per_day out of range")
                return _err("VALIDATION_ERROR", "max_requests_per_day must be between 0 and 1000000")
        if max_files_bytes is not None:
            if not isinstance(max_files_bytes, int) or max_files_bytes < 0 or max_files_bytes > 1099511627776:
                _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="max_files_bytes out of range")
                return _err("VALIDATION_ERROR", "max_files_bytes must be between 0 and 1099511627776")
        if status is not None and status not in ("active", "suspended", "deleted"):
            _audit("VALIDATION_ERROR", workspace_id_ctx=workspace_id, error_code="validation_error", error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "suspended", "deleted"])

        ws, key, ecode, emsg = _resolve_auth_for_workspace(workspace_id)
        if ecode:
            _audit(ecode, workspace_id_ctx=workspace_id, error_code=ecode.lower(), error_message=emsg)
            return _err(ecode, emsg)

        workspaces = _load("workspaces.json")
        idx = next((i for i, w in enumerate(workspaces) if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if idx is None:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="Workspace not found")
            return _err("NOT_FOUND", "Workspace not found")
        w = workspaces[idx]

        # unique(name)
        if name is not None and name != w.get("name"):
            if any(isinstance(ow, dict) and ow.get("id") != workspace_id and ow.get("name") == name for ow in workspaces):
                _audit("CONFLICT", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="conflict", error_message="Workspace name already exists")
                return _err("CONFLICT", "Workspace name already exists")

        # lifecycle transitions
        if status is not None and status != w.get("status"):
            transitions = {
                "active": {"suspended", "deleted"},
                "suspended": {"active", "deleted"},
                "deleted": set()
            }
            cur = w.get("status")
            if cur not in transitions or status not in transitions[cur]:
                _audit("INVALID_TRANSITION", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="invalid_transition", error_message="Invalid workspace status transition")
                return _err("INVALID_TRANSITION", "Invalid workspace status transition", from_status=cur, to_status=status)

        # policy: allow enabling web search only if not disallowed; no extra policy store exists, so allow.
        now = _now_iso()
        changed = False
        for field, val in (("name", name), ("vertex_model", vertex_model), ("allow_web_search", allow_web_search),
                           ("max_requests_per_day", max_requests_per_day), ("max_files_bytes", max_files_bytes), ("status", status)):
            if val is not None and w.get(field) != val:
                w[field] = val
                changed = True

        if not changed:
            _audit("NOT_FOUND", workspace_id_ctx=workspace_id, api_key_id=key.get("id"), error_code="not_found", error_message="No changes to apply")
            return _err("NOT_FOUND", "No changes to apply")

        w["updated_at"] = now
        workspaces[idx] = w
        _save("workspaces.json", workspaces)

        _audit("succeeded", workspace_id_ctx=workspace_id, api_key_id=key.get("id"))
        return {"workspace": w}
    except Exception as e:
        _audit("failed", workspace_id_ctx=workspace_id, error_code="internal_error", error_message=str(e))
        return _err("CONFLICT", "Internal error", detail=str(e))
